package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.ObjectCodec;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TokenBuffer.writeNumber(long l)
 */
public class TokenBuffer_writeNumber_TriageGen1Test {

    private ObjectCodec codec;
    private TokenBuffer tokenBuffer;

    @Before
    public void setUp() {
        codec = new ObjectMapper();
        tokenBuffer = new TokenBuffer(codec);
    }

    @Test
    public void testWriteNumber_PositiveLong() throws IOException {
        long value = 123456789L;
        tokenBuffer.writeNumber(value);

        // Verify the token type is VALUE_NUMBER
        assertEquals(JsonToken.VALUE_NUMBER, tokenBuffer.firstToken());

        // To verify the actual content, we serialize to a generator or use a parser
        // Since TokenBuffer stores tokens internally, we check if it can be parsed back
        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER, parser.nextToken());
        assertEquals(value, parser.getLongValue());
    }

    @Test
    public void testWriteNumber_NegativeLong() throws IOException {
        long value = -987654321L;
        tokenBuffer.writeNumber(value);

        assertEquals(JsonToken.VALUE_NUMBER, tokenBuffer.firstToken());

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER, parser.nextToken());
        assertEquals(value, parser.getLongValue());
    }

    @Test
    public void testWriteNumber_Zero() throws IOException {
        long value = 0L;
        tokenBuffer.writeNumber(value);

        assertEquals(JsonToken.VALUE_NUMBER, tokenBuffer.firstToken());

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER, parser.nextToken());
        assertEquals(value, parser.getLongValue());
    }

    @Test
    public void testWriteNumber_MaxLong() throws IOException {
        long value = Long.MAX_VALUE;
        tokenBuffer.writeNumber(value);

        assertEquals(JsonToken.VALUE_NUMBER, tokenBuffer.firstToken());

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER, parser.nextToken());
        assertEquals(value, parser.getLongValue());
    }

    @Test
    public void testWriteNumber_MinLong() throws IOException {
        long value = Long.MIN_VALUE;
        tokenBuffer.writeNumber(value);

        assertEquals(JsonToken.VALUE_NUMBER, tokenBuffer.firstToken());

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER, parser.nextToken());
        assertEquals(value, parser.getLongValue());
    }

    @Test
    public void testWriteNumber_MultipleCalls() throws IOException {
        tokenBuffer.writeNumber(10L);
        tokenBuffer.writeNumber(20L);

        JsonParser parser = tokenBuffer.asParser();

        assertEquals(JsonToken.VALUE_NUMBER, parser.nextToken());
        assertEquals(10L, parser.getLongValue());

        assertEquals(JsonToken.VALUE_NUMBER, parser.nextToken());
        assertEquals(20L, parser.getLongValue());
    }

    @Test
    public void testWriteNumber_WithContext() throws IOException {
        // Testing with a different constructor to ensure no side effects
        TokenBuffer tb = new TokenBuffer(codec, true);
        tb.writeNumber(5L);

        JsonParser parser = tb.asParser();
        assertEquals(JsonToken.VALUE_NUMBER, parser.nextToken());
        assertEquals(5L, parser.getLongValue());
    }
}
